const servicesByType = new Map<Service_ServiceType, ServiceDescriptor>(SERVICES.map((srv) => [srv.type, srv]));

export function serviceByType(t: Service_ServiceType): ServiceDescriptor | undefined {
	return servicesByType.get(t);
}
